#!/usr/bin/env node
/**
 * Generated by devkit. Do not edit: run `devkit-init` to update it, and put this app's own steps in
 * its `dev:container` npm script.
 *
 * Starts this checkout's devkit stack. On the host it copies inherited worktree files, loads
 * `.env`, asks devkit for this checkout's ports, hostname and database, and runs `compose.dev.yml`.
 * Compose then starts this same runner inside the container with `--container-runtime`, where it
 * hands over to `npm run dev:container`: the app's database preparation and dev servers.
 *
 * Options: `--down` stops the stack, `--fresh` asks `dev:container` for a fresh database (it sees
 * `DEVKIT_FRESH=1`), and devkit's own `--background` and `--open` work as its README describes.
 */
import { spawn } from 'node:child_process'
import { existsSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

import {
  checkoutCompose,
  checkoutComposeLifecycle,
  inheritWorktreeFiles,
  preflight,
} from '@dynamic-solutions-canada/devkit'

const repoRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../..',
)
const envPath = path.join(repoRoot, '.env')
const fresh =
  process.argv.includes('--fresh') || process.env.DEVKIT_FRESH === '1'
const teardown = process.argv.includes('--down')
const containerRuntime = process.argv.includes('--container-runtime')

/**
 * Inside the container: hand over to the app's own preparation and dev servers. Stop signals are
 * passed on, because Compose signals only this process and the app's servers must shut down too.
 */
function runContainer() {
  const child = spawn('npm', ['run', 'dev:container'], {
    cwd: repoRoot,
    env: { ...process.env, DEVKIT_FRESH: fresh ? '1' : '0' },
    stdio: 'inherit',
  })
  for (const signal of ['SIGINT', 'SIGTERM']) {
    process.on(signal, () => child.kill(signal))
  }
  child.on('exit', (code, signal) => process.exit(code ?? (signal ? 1 : 0)))
}

/** Prints the checkout's routed and direct URLs once preflight has chosen them. */
function printUrls(state) {
  for (const line of state.lines) console.log(`[dev] ${line}`)
  const { identity } = state
  const label = identity.isPrimary
    ? identity.repoName
    : `${identity.repoName} / ${identity.worktreeName}`
  console.log('')
  console.log(`  ${label}  ->  ${state.url}`)
  console.log(`  direct  ->  ${state.directUrl}`)
  console.log('')
}

/** On the host: prepare this checkout through devkit, then run its Compose stack. */
async function runHost() {
  await inheritWorktreeFiles({ repoRoot })

  // Match dotenv semantics: explicit shell values win over inherited or checkout-local values.
  if (existsSync(envPath)) process.loadEnvFile(envPath)

  let state
  try {
    state = await preflight({ repoRoot, teardown })
  } catch (error) {
    console.error(
      `\n[dev] ${error instanceof Error ? error.message : String(error)}\n`,
    )
    process.exit(1)
  }
  if (!state) {
    console.error(
      '\n[dev] Devkit is not enabled; run `npm run dev:bootstrap` once on this host.\n',
    )
    process.exit(1)
  }
  Object.assign(process.env, state.env)

  const invocation = checkoutCompose(state, {
    files: [path.join(repoRoot, 'compose.dev.yml')],
    projectDirectory: repoRoot,
    env: {
      DEVKIT_WEB_PORT: String(state.ports.web),
      DEVKIT_FRESH: fresh ? '1' : '0',
      HOST_UID: String(process.getuid?.() ?? 1000),
      HOST_GID: String(process.getgid?.() ?? 1000),
    },
  })
  const lifecycle = checkoutComposeLifecycle(state, invocation)
  if (teardown) process.exit(lifecycle.stop())

  printUrls(state)
  try {
    process.exit(await lifecycle.run(['up', '--build', '--remove-orphans']))
  } catch (error) {
    console.error(`[dev] could not start Docker Compose: ${error.message}`)
    process.exit(1)
  }
}

if (containerRuntime) runContainer()
else await runHost()
